/* ML shelf, Part 8, Lesson 39: Recurrent neural networks (Core). The course export has no material on RNNs, but RNN questions are on every practice final (exploding and vanishing gradients, gradient clipping, teacher forcing and exposure bias, choosing nn.LSTM for a task). So the order follows Andrew Ng's Deep Learning Specialization course 5 week 1 (Why sequence models, Notation, Recurrent neural network model, Backpropagation through time, Different types of RNNs, Language model and sequence generation, Sampling novel sequences, Vanishing gradients with RNNs), with Goodfellow, Bengio and Courville chapter 10, Dive into Deep Learning chapter 9, Pascanu, Mikolov and Bengio (2013) for clipping and Bengio et al. (2015) for exposure bias.
   Data: card 8 trains nn.RNN(1, 32) and nn.LSTM(1, 32) on a fresh remember-the-first-input task (first input plus or minus 1, then N(0, 1) distractors), Adam 3e-3, batch 64, clip 1.0, seeds 0 to 2, PyTorch 2.15 on the CPU. Card 9 runs a character RNN (nn.RNN(16, 32) and a linear head, trained with teacher forcing on five fresh sentences, weights rounded to 2 decimals) live in the page. */
const C = ML.C;
const tx = (x, y, t, a, cls) => `<text class="${cls || "ts"}" x="${x}" y="${y}"${a ? ` text-anchor="${a}"` : ""}>${t}</text>`;
const f = (v, d) => { const s = (+v).toFixed(d == null ? 4 : d); return /^-0(\.0*)?$/.test(s) ? s.slice(1) : s; };
const mn = v => String(v).replace(/-/g, "−");
const fm = (v, d) => mn(f(v, d));
const cm = v => mn(Math.round(v).toLocaleString("en-US"));
const RO = items => ML.readout(items.map(([k, v]) => [k, mn(v)]));
const TB = (head, rows) => `<table style="width:100%;border-collapse:collapse;font-size:13px;margin-top:6px"><tr>${head.map(h => `<th style="text-align:left;padding:4px 6px;border-bottom:1.5px solid var(--line);color:var(--muted);font-weight:600">${h}</th>`).join("")}</tr>${rows.map(r => `<tr>${r.map(c => `<td style="padding:4px 6px;border-bottom:1px solid var(--line);vertical-align:top">${c}</td>`).join("")}</tr>`).join("")}</table>`;
const legend = (items, x0, y, dx) => items.map(([lab, col, dash], i) => `<line x1="${x0 + i * dx}" y1="${y - 4}" x2="${x0 + i * dx + 18}" y2="${y - 4}" stroke="${col}" stroke-width="3" ${dash ? `stroke-dasharray="${dash}"` : ""}/>` + tx(x0 + i * dx + 23, y, lab)).join("");
const vec = (v, d) => "(" + v.map(x => fm(x, d == null ? 4 : d)).join(", ") + ")";
const ex = v => { if (v === 0) return "0"; const e = Math.floor(Math.log10(Math.abs(v))); return Math.abs(e) < 4 ? f(v, Math.max(0, 3 - e)) : mn(v.toExponential(1)); };
const cell = (x, y, w, h, on, col, lines) => `<g class="${on ? (col || "c-teal") : "c-gray"}"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8" stroke-width="${on ? 1.6 : 0.6}"/></g>` + lines.map((t, i) => tx(x + w / 2, y + h / 2 + (i - (lines.length - 1) / 2) * 16 + 5, t, "middle", i === 0 ? "th" : "ts")).join("");

/* card 2: one RNN with n_a = 2, n_x = 1, n_y = 1, Ng's notation */
const R2 = { Waa: [[0.5, -1], [1, 0.5]], Wax: [1, -0.5], ba: [0, 0.2], Wya: [1, 2], by: 0, xs: [1, 0, -1, 2] };
const run2 = () => { let a = [0, 0]; const out = [{ a }]; R2.xs.forEach(x => { const z = [0, 1].map(i => R2.Waa[i][0] * a[0] + R2.Waa[i][1] * a[1] + R2.Wax[i] * x + R2.ba[i]); a = z.map(Math.tanh); out.push({ x, z, a, y: R2.Wya[0] * a[0] + R2.Wya[1] * a[1] + R2.by }); }); return out; };
/* card 5: scalar RNN h_t = tanh(w h_{t-1} + u x_t), output v h_T, loss (yhat - y)^2 / 2 */
const R5 = { w: 0.5, u: 1, v: 2, xs: [1, -1, 2], y: 1 };
const bptt = P => {
  const h = [0], z = [];
  P.xs.forEach(x => { const q = P.w * h[h.length - 1] + P.u * x; z.push(q); h.push(Math.tanh(q)); });
  const T = P.xs.length, yh = P.v * h[T], L = 0.5 * (yh - P.y) ** 2;
  let d = (yh - P.y) * P.v, gw = 0, gu = 0; const back = [];
  for (let t = T; t >= 1; t--) { const s = 1 - h[t] ** 2, dz = d * s; back.unshift({ t, dh: d, s, dz, cw: dz * h[t - 1], cu: dz * P.xs[t - 1] }); gw += dz * h[t - 1]; gu += dz * P.xs[t - 1]; d = dz * P.w; }
  return { h, z, yh, L, back, gw, gu, gv: (yh - P.y) * h[T], dh0: d };
};
/* card 7: Pascanu's one-unit cliff, h_t = w sigmoid(h_{t-1}) + b, 50 steps from h_0 = 0.5, loss (h_50 - y)^2 */
const CL = { w: 5, T: 50, h0: 0.5, y: -2.68, alpha: 0.02 };
const cliff = b => { let h = CL.h0, d = 0; for (let t = 0; t < CL.T; t++) { const s = 1 / (1 + Math.exp(-h)); d = CL.w * s * (1 - s) * d + 1; h = CL.w * s + b; } return { L: (h - CL.y) ** 2, g: 2 * (h - CL.y) * d, h }; };

